// Teachers' timetable planner — English, grades 3–9 (shape: ./schema.js).
// The English Curriculum 2020 sets levels (Pre-A1 ג׳, A1 ד׳–ו׳, A2 ז׳–ט׳), can-dos, lexical bands and
// grammar structures by grade, but no unit order (docs/curriculum/english.md). The thematic units below
// are a recommended order built on those: each unit = vocabulary topic + the grade's grammar structure +
// a reading/unseen + a writing/speaking task. Grade 3 starts with 3–4 months of listening and speaking
// before any reading (MUST #1 of the Pre-Foundation guidelines).

const TYPES = { g: 'grammar', v: 'vocab', r: 'reading', u: 'unseen', b: 'booklet' }
// 'g:to-be v:grade-3/school u:en-g3-my-cat-mitzi' → [{ type, slug }, ...]
const L = s => s.split(' ').filter(Boolean).map(x => {
  const i = x.indexOf(':')
  return { type: TYPES[x.slice(0, i)], slug: x.slice(i + 1) }
})
const unit = (id, title, hours, goals, concepts, steps) => ({
  id, title, hours, goals, concepts,
  steps: steps.map(([t, goal, activity, practice, links = '']) => ({ title: t, goal, activity, practice, links: L(links) })),
})

const NOTE = 'סדר מומלץ לפי תוכנית האנגלית 2020 — המשרד לא קובע סדר יחידות; המורה יכול לשנות'
const SRC = { title: 'English Curriculum 2020 — משרד החינוך', url: 'https://meyda.education.gov.il/files/Mazkirut_Pedagogit/English/Curriculum2020.pdf' }
const SRC_PRE = { title: 'Guidelines for the Teaching of English at the Pre-Foundation Level (2019) ו-Curriculum 2020', url: 'https://meyda.education.gov.il/files/Mazkirut_Pedagogit/English/prefoundationcando.pdf' }
const seq = (grade, hoursPerWeek, source, units) => ({ subject: 'english', grade, hoursPerWeek, official: false, source, note: NOTE, units })

